const BY_ID = new Map(BNS_SECTIONS.map((s) => [s.id, s]));

export function bnsSectionById(id: string) {
  return BY_ID.get(id);
}

export function bnsSectionsInChapter(chapter: string) {
  return BNS_SECTIONS.filter((s) => s.chapter === chapter);
}

export function bnsForIpc(query: string): BnsSection[] {
  const q = query.trim().toLowerCase().replace(/^ipc\s*/, "").replace(/^s(ection)?\.?\s*/, "");
  if (!q) return [];
  return BNS_SECTIONS.filter((s) => {
    if (!s.ipc) return false;
    const hay = s.ipc.toLowerCase();
    if (hay === q) return true;
    return hay.split(/[^0-9a-z]+/).includes(q);
  });
}

export function mentionsBnsSection(hay: string, id: string) {
  const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`(^|[^0-9A-Za-z])${escaped}(?![0-9A-Za-z])`).test(hay);
}


export function sectionTopicId(sectionId: string) {
  return `s-${sectionId.toLowerCase()}`
}

export function sectionIdFromTopicId(topicId: string): string | null {
  const match = topicId.match(/^s-(\d+[a-z]*)$/i)
  return match?.[1] ?? null
}
